///   12. `[]` memo_program
#[derive(Clone, Debug)]
pub struct SettleDvpCpiBuilder<'a, 'b> {
    instruction: Box<SettleDvpCpiBuilderInstruction<'a, 'b>>,
}

impl<'a, 'b> SettleDvpCpiBuilder<'a, 'b> {
    pub fn new(program: &'b solana_account_info::AccountInfo<'a>) -> Self {
        let instruction = Box::new(SettleDvpCpiBuilderInstruction {
            __program: program,
            settlement_authority: None,
            swap_dvp: None,
            mint_a: None,
            mint_b: None,
            dvp_ata_a: None,
            dvp_ata_b: None,
            user_a_destination_ata_b: None,
            user_b_destination_ata_a: None,
            user_a_ata_a: None,
            user_b_ata_b: None,
            token_program_a: None,
            token_program_b: None,
            memo_program: None,
            leg_a_extras_count: None,
            __remaining_accounts: Vec::new(),
        });
        Self { instruction }
    }
    /// Must equal dvp.settlement_authority; receives closed-account rent
    #[inline(always)]
    pub fn settlement_authority(
        &mut self,
        settlement_authority: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.settlement_authority = Some(settlement_authority);
        self
    }
    /// SwapDvp PDA (signs CPIs, then closed)
    #[inline(always)]
    pub fn swap_dvp(&mut self, swap_dvp: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.swap_dvp = Some(swap_dvp);
        self
    }
    /// Must equal dvp.mint_a
    #[inline(always)]
    pub fn mint_a(&mut self, mint_a: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.mint_a = Some(mint_a);
        self
    }
    /// Must equal dvp.mint_b
    #[inline(always)]
    pub fn mint_b(&mut self, mint_b: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.mint_b = Some(mint_b);
        self
    }
    /// Asset escrow (drained, then closed)
    #[inline(always)]
    pub fn dvp_ata_a(&mut self, dvp_ata_a: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.dvp_ata_a = Some(dvp_ata_a);
        self
    }
    /// Cash escrow (drained, then closed)
    #[inline(always)]
    pub fn dvp_ata_b(&mut self, dvp_ata_b: &'b solana_account_info::AccountInfo<'a>) -> &mut Self {
        self.instruction.dvp_ata_b = Some(dvp_ata_b);
        self
    }
    /// user_a_settlement_destination's ATA for mint_b; receives the cash leg (destination defaults to user_a)
    #[inline(always)]
    pub fn user_a_destination_ata_b(
        &mut self,
        user_a_destination_ata_b: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.user_a_destination_ata_b = Some(user_a_destination_ata_b);
        self
    }
    /// user_b_settlement_destination's ATA for mint_a; receives the asset leg (destination defaults to user_b)
    #[inline(always)]
    pub fn user_b_destination_ata_a(
        &mut self,
        user_b_destination_ata_a: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.user_b_destination_ata_a = Some(user_b_destination_ata_a);
        self
    }
    /// user_a's ATA for mint_a; receives any asset-leg surplus refund. Required and must be pre-initialized: anyone can dust the escrow, forcing a surplus refund, and a missing ATA reverts the whole Settle
    #[inline(always)]
    pub fn user_a_ata_a(
        &mut self,
        user_a_ata_a: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.user_a_ata_a = Some(user_a_ata_a);
        self
    }
    /// user_b's ATA for mint_b; receives any cash-leg surplus refund. Required and must be pre-initialized, same as user_a_ata_a
    #[inline(always)]
    pub fn user_b_ata_b(
        &mut self,
        user_b_ata_b: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.user_b_ata_b = Some(user_b_ata_b);
        self
    }
    /// SPL Token or Token-2022 program; must own mint_a
    #[inline(always)]
    pub fn token_program_a(
        &mut self,
        token_program_a: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.token_program_a = Some(token_program_a);
        self
    }
    /// SPL Token or Token-2022 program; must own mint_b
    #[inline(always)]
    pub fn token_program_b(
        &mut self,
        token_program_b: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.token_program_b = Some(token_program_b);
        self
    }
    /// SPL Memo program; only used for destinations that require a memo
    #[inline(always)]
    pub fn memo_program(
        &mut self,
        memo_program: &'b solana_account_info::AccountInfo<'a>,
    ) -> &mut Self {
        self.instruction.memo_program = Some(memo_program);
        self
    }
    #[inline(always)]
    pub fn leg_a_extras_count(&mut self, leg_a_extras_count: u8) -> &mut Self {
        self.instruction.leg_a_extras_count = Some(leg_a_extras_count);
        self
    }
    /// Add an additional account to the instruction.
    #[inline(always)]
    pub fn add_remaining_account(
        &mut self,
        account: &'b solana_account_info::AccountInfo<'a>,
        is_writable: bool,
        is_signer: bool,
    ) -> &mut Self {
        self.instruction
            .__remaining_accounts
            .push((account, is_writable, is_signer));
        self
    }
    /// Add additional accounts to the instruction.
    ///
    /// Each account is represented by a tuple of the `AccountInfo`, a `bool` indicating whether the account is writable or not,
    /// and a `bool` indicating whether the account is a signer or not.
    #[inline(always)]
    pub fn add_remaining_accounts(
        &mut self,
        accounts: &[(&'b solana_account_info::AccountInfo<'a>, bool, bool)],
    ) -> &mut Self {
        self.instruction
            .__remaining_accounts
            .extend_from_slice(accounts);
        self
    }
    #[inline(always)]
    pub fn invoke(&self) -> solana_program_error::ProgramResult {
        self.invoke_signed(&[])
    }
    #[allow(clippy::clone_on_copy)]
    #[allow(clippy::vec_init_then_push)]
    pub fn invoke_signed(&self, signers_seeds: &[&[&[u8]]]) -> solana_program_error::ProgramResult {
        let args = SettleDvpInstructionArgs {
            leg_a_extras_count: self
                .instruction
                .leg_a_extras_count
                .clone()
                .expect("leg_a_extras_count is not set"),
        };
        let instruction = SettleDvpCpi {
            __program: self.instruction.__program,

            settlement_authority: self
                .instruction
                .settlement_authority
                .expect("settlement_authority is not set"),

            swap_dvp: self.instruction.swap_dvp.expect("swap_dvp is not set"),

            mint_a: self.instruction.mint_a.expect("mint_a is not set"),

            mint_b: self.instruction.mint_b.expect("mint_b is not set"),

            dvp_ata_a: self.instruction.dvp_ata_a.expect("dvp_ata_a is not set"),

            dvp_ata_b: self.instruction.dvp_ata_b.expect("dvp_ata_b is not set"),

            user_a_destination_ata_b: self
                .instruction
                .user_a_destination_ata_b
                .expect("user_a_destination_ata_b is not set"),

            user_b_destination_ata_a: self
                .instruction
                .user_b_destination_ata_a
                .expect("user_b_destination_ata_a is not set"),

            user_a_ata_a: self
                .instruction
                .user_a_ata_a
                .expect("user_a_ata_a is not set"),

            user_b_ata_b: self
                .instruction
                .user_b_ata_b
                .expect("user_b_ata_b is not set"),

            token_program_a: self
                .instruction
                .token_program_a
                .expect("token_program_a is not set"),

            token_program_b: self
                .instruction
                .token_program_b
                .expect("token_program_b is not set"),

            memo_program: self
                .instruction
                .memo_program
                .expect("memo_program is not set"),
            __args: args,
        };
        instruction.invoke_signed_with_remaining_accounts(
            signers_seeds,
            &self.instruction.__remaining_accounts,
        )
    }
}

#[derive(Clone, Debug)]
struct SettleDvpCpiBuilderInstruction<'a, 'b> {
    __program: &'b solana_account_info::AccountInfo<'a>,
    settlement_authority: Option<&'b solana_account_info::AccountInfo<'a>>,
    swap_dvp: Option<&'b solana_account_info::AccountInfo<'a>>,
    mint_a: Option<&'b solana_account_info::AccountInfo<'a>>,
    mint_b: Option<&'b solana_account_info::AccountInfo<'a>>,
    dvp_ata_a: Option<&'b solana_account_info::AccountInfo<'a>>,
    dvp_ata_b: Option<&'b solana_account_info::AccountInfo<'a>>,
    user_a_destination_ata_b: Option<&'b solana_account_info::AccountInfo<'a>>,
    user_b_destination_ata_a: Option<&'b solana_account_info::AccountInfo<'a>>,
    user_a_ata_a: Option<&'b solana_account_info::AccountInfo<'a>>,
    user_b_ata_b: Option<&'b solana_account_info::AccountInfo<'a>>,
    token_program_a: Option<&'b solana_account_info::AccountInfo<'a>>,
    token_program_b: Option<&'b solana_account_info::AccountInfo<'a>>,
    memo_program: Option<&'b solana_account_info::AccountInfo<'a>>,
    leg_a_extras_count: Option<u8>,
    /// Additional instruction accounts `(AccountInfo, is_writable, is_signer)`.
    __remaining_accounts: Vec<(&'b solana_account_info::AccountInfo<'a>, bool, bool)>,
}
